17	const runCli = (input: string): Promise<CliRun> =>
18	  new Promise((resolve) => {
19	    const child = execFile(
20	      "npx",
21	      ["tsx", "src/cli.ts"],
22	      (error, stdout, stderr) => {
23	        resolve({
24	          stdout,
25	          stderr,
26	          code: error && typeof error.code === "number" ? error.code : 0,
27	        });
28	      },
29	    );
30	    child.stdin?.end(input);
31	  });
