const runClaimStep = (
  step: ClaimStep,
  steps: Step[],
  remainingCaps: Map<number, number>,
): StepResult => {
  const insuredItems = insuredItemsOf(step, steps);
  const cap = remainingCaps.get(step.policy) ?? payoutCapOf(insuredItems);
  const result = claim(insuredItems, step.incident, cap);
  remainingCaps.set(step.policy, result.remainingCap);
  return result;
};

const runStep = (
  customer: ScenarioCustomer,
  step: Step,
  steps: Step[],
  stepIndex: number,
  remainingCaps: Map<number, number>,
): StepResult =>
  step.op === "claim"
    ? runClaimStep(step, steps, remainingCaps)
    : runQuoteStep(customer, step, previousContractsAt(steps, stepIndex));

export const runScenario = (scenario: Scenario): StepResult[] => {
  const remainingCaps = new Map<number, number>();
  return scenario.steps.map((step, stepIndex) =>
    runStep(scenario.customer, step, scenario.steps, stepIndex, remainingCaps),
  );
};
